fn value(j: &Json) -> Value {
    match j {
        Json::Object(m) if m.len() == 1 && m.contains_key("$f") => {
            let bits = u64::from_str_radix(m["$f"].as_str().unwrap(), 16).unwrap();
            Value::Float(f64::from_bits(bits))
        }
        Json::Array(items) => Value::List(items.iter().map(value).collect()),
        Json::Object(m) => Value::Map(m.iter().map(|(k, v)| (k.clone(), value(v))).collect()),
        other => Value::from(other),
    }
}

fn bindings() -> Bindings {
    let json: Json = serde_json::from_str(BINDINGS).unwrap();
    json.as_object()
        .unwrap()
        .iter()
        .map(|(k, v)| (k.clone(), value(v)))
        .collect()
}

#[test]
fn syntax_forms_match_upstream() {
    let vars = bindings();
    let mut failures = Vec::new();
    for (class, expr, expected) in CASES {
        let expr: String = serde_json::from_str(expr).unwrap();
        let expected: Json = serde_json::from_str(expected).unwrap();
        let got = eval_expr_with_mapping(&expr, &vars);
        let agrees = match (expected.get("ok"), &got) {
            (Some(ok), Ok(v)) => value(ok).py_eq(v) && same_type(&value(ok), v),
            (None, Err(_)) => true,
            // A result `Value` cannot hold (bytes): not comparable.
            (Some(_), Err(e)) => e.is_unrepresentable(),
            _ => false,
        };
        if !agrees {
            failures.push(format!(
                "[{class}] {expr:?}: upstream {expected}, got {got:?}"
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} case(s) differ from upstream:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

/// `1`, `1.0` and `True` compare equal in Python but are different results.
fn same_type(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::List(x), Value::List(y)) => {
            x.len() == y.len() && x.iter().zip(y).all(|(p, q)| same_type(p, q))
        }
        (Value::Map(x), Value::Map(y)) => {
            x.len() == y.len()
                && x.iter()
                    .all(|(k, p)| y.get(k).is_some_and(|q| same_type(p, q)))
        }
        _ => std::mem::discriminant(a) == std::mem::discriminant(b),
    }
}

/// `test_comparisons` of upstream `tests/test_utils/test_eval_utils.py`: `is` and
/// `is not` against `None`.
#[test]
fn test_comparisons_is_none() {
    let eval = |expr: &str, x: Value| {
        let mut vars = Bindings::new();
        vars.insert("x".into(), x);
        eval_expr_with_mapping(expr, &vars).unwrap()
    };
    assert_eq!(eval("x is None", Value::Null), Value::Bool(true));
    assert_eq!(eval("x is None", Value::Int(1)), Value::Bool(false));
    assert_eq!(eval("x is not None", Value::Int(1)), Value::Bool(true));
    assert_eq!(eval("x is not None", Value::Null), Value::Bool(false));
}
